function Icon({ name, size = 18, className = '' }: { name: IconName; size?: number; className?: string }) { return <svg className={`icon ${className}`} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg> }
function sizeLabel(size: number) { if (!size) return '—'; if(size < 1024) return `${size} B`; if(size < 1048576) return `${(size / 1024).toFixed(1)} KB`; if(size < 1073741824) return `${(size / 1048576).toFixed(1)} MB`; return `${(size / 1073741824).toFixed(2)} GB` }
