const kindLabel = (kind: AssetRecord['kind']) => ({ folder: '素材文件夹', archive: '压缩包', unitypackage: 'Unity 素材包', file: '文件', 'unity-project': 'Unity 工程' }[kind]);
function assetIntroduction(asset:AssetRecord):string {
  const text=(asset.online.description??'').replace(/https?:\/\/\S+/g,'').replace(/<[^>]+>/g,' ').split(/(?:利用規約|使用条款|版权声明|Terms of Use|License)/i)[0].trim();
  if(text){const characters=Array.from(text.replace(/\s+/g,' '));return characters.slice(0,300).join('')+(characters.length>300?'…':'')}
  return `本地${kindLabel(asset.kind)}，尚未获取商品介绍。可查看本地文件或添加商品来源了解用途。`;
}
function HoverPreview({asset,anchor,onEnter,onLeave}:{asset:AssetRecord;anchor:DOMRect;onEnter:()=>void;onLeave:()=>void}) {
  const ref=useRef<HTMLDivElement>(null);const [position,setPosition]=useState({x:Math.min(anchor.right+12,window.innerWidth-340),y:anchor.top});
  useLayoutEffect(()=>{const r=ref.current?.getBoundingClientRect();if(!r)return;const x=anchor.right+r.width+20>window.innerWidth?anchor.left-r.width-12:anchor.right+12;setPosition({x:Math.max(8,Math.min(x,window.innerWidth-r.width-8)),y:Math.max(8,Math.min(anchor.top,window.innerHeight-r.height-8))})},[asset.id,anchor]);
  const local=[...new Set([...asset.localAvatars,...(asset.manual.avatars??[])])];const missing=(asset.online.avatars??[]).filter(a=>!local.some(b=>b.toLowerCase()===a.toLowerCase()));
  return createPortal(<div className="hover-preview" ref={ref} role="tooltip" aria-label="素材介绍" style={{left:position.x,top:position.y}} onMouseEnter={onEnter} onMouseLeave={onLeave}><div className="hover-cover"><Cover asset={asset}/></div><div className="hover-content"><span className="hover-category">{displayCategory(asset)}{(asset.members?.length??0)>1?` · ${asset.members!.length} 份本地文件`:''}</span><h3>{displayTitle(asset)}</h3>{asset.online.author&&<span className="hover-author">{asset.online.author}</span>}<p>{assetIntroduction(asset)}</p><div className="hover-avatars"><strong>本地适配</strong>{local.length?<div className="compatibility-grid">{local.map(a=><span className="compatibility-avatar local" key={a}><Icon name="check" size={11}/>{a}</span>)}</div>:<span className="help-text">尚未识别</span>}{missing.length>0&&<><strong>商品支持，尚未发现本地版本</strong><div className="compatibility-grid">{missing.map(a=><span className="compatibility-avatar absent" key={a}>{a}</span>)}</div></>}</div></div></div>,document.body);
}
function Compatibility({asset}:{asset:AssetRecord}) {
  const key=(s:string)=>s.toLocaleLowerCase().replace(/[\s_-]/g,'');const local=[...new Set([...(asset.localAvatars??[]),...(asset.manual.avatars??[])])];const localKeys=new Set(local.map(key));const product=[...new Set(asset.online.avatars??[])];const all=[...product,...local.filter(a=>!product.some(b=>key(a)===key(b)))];const unmatched=product.filter(a=>!localKeys.has(key(a)));
  const evidence=asset.localEvidence??[];
  return <div className="detail-section compatibility-section"><div className="section-label">适配对照<span>{local.length} 个本地 · {product.length} 个商品支持</span></div><div className="compatibility-legend"><span><i className="local-dot"/>本地适配</span><span><i className="absent-dot"/>尚未发现本地版本</span></div>{all.length?<div className="compatibility-grid">{all.map(avatar=>{const found=localKeys.has(key(avatar));const files=evidence.filter(e=>key(e.avatar)===key(avatar)).flatMap(e=>e.files);return <span key={avatar} className={`compatibility-avatar ${found?'local':'absent'}`} title={found?files.length?files.join('\n'):asset.manual.avatars?.some(a=>key(a)===key(avatar))?'你手动确认的本地适配':'由本地文件名称识别':'BOOTH 商品支持，但未发现本地文件'}><Icon name={found?'check':'box'} size={12}/>{avatar}</span>})}</div>:<p className="help-text">尚未识别到适配名称，可以在下方手动确认。</p>}<div className="compatibility-summary"><span>本地适配：{local.length?local.join('、'):'尚无识别依据'}</span><span>BOOTH 商品适配：{product.length?product.join('、'):'尚未获取'}</span>{unmatched.length>0&&<span className="absent-summary">未发现本地：{unmatched.join('、')}</span>}</div><p className="help-text">{asset.compatibilityComplete===false?'名称识别可能不完整。灰色表示尚无本地证据，不代表确定缺少该版本。':'灰色表示 BOOTH 支持、但尚未发现本地文件的版本。'}</p>{evidence.length>0&&<details className="evidence-list"><summary>查看本地识别依据</summary>{evidence.map((e,i)=><div key={`${e.avatar}-${i}`}><strong>{e.avatar}<small>{e.basis==='archive-entry'?'压缩包内名称':e.basis==='manual'?'手动确认':'本地文件名'}</small></strong>{e.files.map((file,n)=><span key={`${file}-${n}`} title={file}>{file}</span>)}</div>)}</details>}</div>;
}
function OriginalAnnotations({member,asset}:{member:LocalMember;asset:AssetRecord}) {
  const manual=member.manual;if(!manual)return null;
  const keys=['title','category','tags','avatars','notes','favorite','coverFile','projectStatus','relatedIds'] as const;
  const changed=keys.filter(key=>manual[key]!==undefined&&JSON.stringify(manual[key])!==JSON.stringify(asset.manual[key]));
  if(!changed.length)return null;
  const labels:Record<typeof keys[number],string>={title:'原显示名称',category:'原分类',tags:'原标签',avatars:'原手动适配',notes:'原备注',favorite:'原收藏状态',coverFile:'原封面',projectStatus:'原工程状态',relatedIds:'原关联素材'};
  const value=(key:typeof keys[number])=>key==='favorite'?(manual.favorite?'已收藏':'未收藏'):key==='coverFile'?'单独设置的封面，已保留':key==='relatedIds'?`${manual.relatedIds?.length??0} 项`:Array.isArray(manual[key])?(manual[key] as string[]).join('、'):String(manual[key]);
  return <details className="member-notes"><summary>此文件原有标注</summary>{changed.map(key=><p key={key}><strong>{labels[key]}</strong>{value(key)||'未填写'}</p>)}</details>;
}
function Members({asset,api,run}:{asset:AssetRecord;api:LibraryAPI;run:Runner}) {
  const [context,setContext]=useState<{member:LocalMember;x:number;y:number}|null>(null);const ref=useRef<HTMLDivElement>(null);const members=localFiles(asset);
  useEffect(()=>setContext(null),[asset.id]);
  useLayoutEffect(()=>{if(!context)return;const rect=ref.current?.getBoundingClientRect();if(rect){const x=Math.max(8,Math.min(context.x,window.innerWidth-rect.width-8)),y=Math.max(8,Math.min(context.y,window.innerHeight-rect.height-8));if(x!==context.x||y!==context.y)setContext({...context,x,y})}ref.current?.querySelector<HTMLButtonElement>('button')?.focus()},[context]);
  useEffect(()=>{if(!context)return;const outside=(e:PointerEvent)=>{if(!ref.current?.contains(e.target as Node))setContext(null)};const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();setContext(null)}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const buttons=[...(ref.current?.querySelectorAll<HTMLButtonElement>('button')??[])];const index=buttons.indexOf(document.activeElement as HTMLButtonElement);buttons[(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}else if(e.key==='Tab')setContext(null)};window.addEventListener('pointerdown',outside,true);window.addEventListener('keydown',key);return()=>{window.removeEventListener('pointerdown',outside,true);window.removeEventListener('keydown',key)}},[context]);
  if(members.length<2)return null;
  const open=(e:React.MouseEvent,member:LocalMember)=>{e.preventDefault();e.stopPropagation();setContext({member,x:e.clientX,y:e.clientY})};
  return <div className="local-members"><div className="section-label">合并展示的本地文件<span>{members.length} 份</span></div><p className="help-text">同一素材集中展示，文件仍保存在原来的位置。</p>{members.map(member=><div key={member.path} className={`local-member ${member.missing?'member-missing':''}`} onContextMenu={e=>open(e,member)}><Icon name={member.kind==='folder'?'folder':'box'} size={14}/><div><strong>{member.name}</strong>{member.version&&<small className="member-version">版本 {member.version}</small>}{member.mtimeMs!==undefined&&<small className="member-modified">文件修改：{new Date(member.mtimeMs).toLocaleString('zh-CN')}</small>}<span title={member.path}>{member.path}</span>{member.missing&&<small>本地文件暂时无法找到</small>}<OriginalAnnotations member={member} asset={asset}/></div><button className="icon-button" aria-label={`操作 ${member.name}`} onClick={e=>{e.stopPropagation();const rect=e.currentTarget.getBoundingClientRect();setContext({member,x:rect.right,y:rect.bottom})}}><Icon name="more" size={16}/></button></div>)}{context&&<div ref={ref} role="menu" className="context-menu member-context-menu" style={{left:context.x,top:context.y}} onContextMenu={e=>{e.preventDefault();e.stopPropagation()}}><div className="context-title">{context.member.name}</div><button role="menuitem" onClick={()=>{const {id,path}=context.member;setContext(null);run(()=>api.reveal(id,path))}}><Icon name="folder" size={16}/>打开所在文件夹</button><button role="menuitem" onClick={()=>{const {id,path}=context.member;setContext(null);run(()=>api.copyPath(id,path),'路径已复制')}}><Icon name="copy" size={16}/>复制路径</button></div>}</div>;
}
function Cover({ asset, large = false }: { asset: AssetRecord; large?: boolean }) {
  const src = coverUrl(asset); const [failed, setFailed] = useState(false);
  useEffect(() => setFailed(false), [src]);
  return src && !failed ? <img src={src} onError={() => setFailed(true)} alt="" loading={large ? 'eager' : 'lazy'} /> : <div className={`cover-placeholder cover-${displayCategory(asset)}`}><div className="placeholder-orbit"/><Icon name={asset.kind === 'unity-project' ? 'folder' : displayCategory(asset) === '模型' ? 'spark' : 'box'} size={large ? 54 : 43}/><span>{displayCategory(asset)}</span></div>;
}
const STATUS: Record<string,string> = { pending:'等待补全', matched:'已匹配', review:'待确认', 'not-found':'未找到来源', failed:'稍后重试', blocked:'访问受限' };
