  const [snapshot,setSnapshot] = useState<Snapshot>();
  const [items,setItems] = useState<AssetRecord[]>([]); const [total,setTotal] = useState(0);
  const workspace=useWorkspace();
  const {view,collection,collectionId,search,searchQuery,category,group,avatar,sort,limit,selected}=workspace.state;
  const {setView,setCollection,setSearch,setSearchQuery,setCategory,setGroup,setAvatar,setSort,setLimit,setSelected}=workspace;
  const [loading,setLoading] = useState(true);const [libraryReadError,setLibraryReadError]=useState('');
  const [collections,setCollections]=useState<LibraryCollection[]>([]),[collectionsReady,setCollectionsReady]=useState(false),[tags,setTags]=useState<TagSummary[]>([]),[advanced,setAdvanced]=useState(false);
  const advancedRef=useRef<HTMLDivElement>(null),advancedToggle=useRef<HTMLButtonElement>(null);
  const [detail,setDetail] = useState<AssetRecord|null>(null); const [showDetail,setShowDetail] = useState(true);const [projectOrigin,setProjectOrigin]=useState<AssetRecord|null>(null);
  const [dialog,setDialog] = useState<Dialog|null>(null); const [context,setContext] = useState<Context|null>(null);
  const closeDialog=useCallback(()=>setDialog(null),[]);const closeContext=useCallback(()=>setContext(null),[]);
  const [toast,setToast] = useState<{message:string;error:boolean}|null>(null); const [revision,setRevision] = useState(0);
  const [busy,setBusy] = useState(false); const detailId = useRef<string|null>(null); const toastTimer = useRef<ReturnType<typeof setTimeout>|undefined>(undefined);
  const [boothPage,setBoothPage]=useState(false);
  const [hover,setHover]=useState<{asset:AssetRecord;anchor:DOMRect}|null>(null);const hoverTimer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);const hoverCloseTimer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);
  const zoomRef=useRef(1);const zoomRequests=useRef(0);const zoomSerial=useRef(0);
  const query=workspace.query;
  const tell = useCallback((message:string,error=false) => {setToast({message,error}); clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(null),error?6500:3600)},[]);
  const run = useCallback(async (action:()=>Promise<unknown>,message?:string) => { try {await action();setRevision(r=>r+1); if(message) tell(message); return true} catch(e) {tell(e instanceof Error?e.message:'操作未完成，请稍后重试',true);return false} },[tell]);
  const closeHover=useCallback(()=>{clearTimeout(hoverTimer.current);clearTimeout(hoverCloseTimer.current);setHover(null)},[]);
  const keepHover=()=>{clearTimeout(hoverCloseTimer.current)};
  const leaveHover=()=>{clearTimeout(hoverTimer.current);clearTimeout(hoverCloseTimer.current);hoverCloseTimer.current=setTimeout(()=>setHover(null),140)};
